// `init`: a wizard that asks the questions of the starter procedure (templates/README.md)
// one at a time, or takes the answers without asking, and writes the skeleton of a brain
// with the instruction for the agent that finishes the setup. The text comes from the
// templates read at run time; the views are generated by `index`.
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { createInterface } from "node:readline";
import { formatViolation, lint, severity } from "../lint.ts";
import { loadRepo } from "../repo.ts";
import { type Answers, InitError, type Question, QUESTION_KEYS, QUESTIONS } from "./questions.ts";
import { preflight, type ScaffoldResult, scaffold } from "./scaffold.ts";

const USAGE = `Usage: dotbrain init [<repository>] [--answers <file.json>] [--<question>=<answer>...] [--yes]
Questions: ${QUESTIONS.map((q) => q.key).join(", ")}`;

interface Parsed {
    root: string;
    answers: Answers;
    yes: boolean;
}

function parseArgs(args: string[]): Parsed {
    let root: string | null = null;
    let file: string | null = null;
    let yes = false;
    const given: Answers = {};
    for (let i = 0; i < args.length; i++) {
        const arg = args[i]!;
        if (!arg.startsWith("--")) {
            if (root !== null) throw new InitError(USAGE);
            root = arg;
            continue;
        }
        const eq = arg.indexOf("=");
        const key = eq === -1 ? arg.slice(2) : arg.slice(2, eq);
        if (key === "yes" && eq === -1) {
            yes = true;
            continue;
        }
        const value = eq === -1 ? args[++i] : arg.slice(eq + 1);
        if (value === undefined) throw new InitError(`--${key} needs a value\n${USAGE}`);
        if (key === "answers") file = value;
        else if (QUESTION_KEYS.has(key)) given[key] = value.trim();
        else throw new InitError(`unknown option --${key}\n${USAGE}`);
    }
    const answers: Answers = file === null ? {} : readAnswersFile(file);
    Object.assign(answers, given);
    for (const [k, v] of Object.entries(answers)) {
        const reason = QUESTIONS.find((q) => q.key === k)!.check(v);
        if (reason) throw new InitError(`${k}: ${reason}`);
    }
    return { root: resolve(root ?? "."), answers, yes };
}

function readAnswersFile(file: string): Answers {
    let data: unknown;
    try {
        data = JSON.parse(readFileSync(file, "utf8"));
    } catch (e) {
        throw new InitError(`cannot read the answers file ${file}: ${(e as Error).message}`);
    }
    if (typeof data !== "object" || data === null || Array.isArray(data))
        throw new InitError(`${file}: the answers must be a JSON object`);
    const answers: Answers = {};
    for (const [k, v] of Object.entries(data)) {
        if (!QUESTION_KEYS.has(k)) throw new InitError(`${file}: unknown question "${k}"`);
        if (typeof v !== "string") throw new InitError(`${file}: the answer to "${k}" must be a string`);
        answers[k] = v.trim();
    }
    return answers;
}

type LineReader = ReturnType<typeof lineReader>;

/** Reads lines of standard input one at a time, buffering lines that arrive before they are asked for. */
function lineReader() {
    const rl = createInterface({ input: process.stdin, terminal: false });
    const it = rl[Symbol.asyncIterator]();
    return {
        ask: async (prompt: string): Promise<string | null> => {
            process.stdout.write(prompt);
            const r = await it.next();
            if (r.done) return null;
            if (!process.stdin.isTTY) process.stdout.write("\n");
            return r.value;
        },
        close: () => rl.close(),
    };
}

/** Reports an `InitError` as the exit code 2; any other error is a fault of the tool and is thrown on. */
function failed(e: unknown): number {
    if (e instanceof InitError) {
        console.error(`error: ${e.message}`);
        return 2;
    }
    throw e;
}

/** Fills the missing answers with their defaults; the key of the first one without a default, or null. */
function takeDefaults(root: string, answers: Answers, missing: Question[]): string | null {
    for (const q of missing) {
        const d = q.default(root);
        if (d === null) return q.key;
        answers[q.key] = d;
    }
    return null;
}

/** Asks one question until its answer is valid; null when the input ends. */
async function ask(reader: LineReader, q: Question, d: string | null): Promise<string | null> {
    const choices = q.choices ? ` (${q.choices.join("/")})` : "";
    for (;;) {
        const line = await reader.ask(`${q.prompt}${choices}${d !== null ? ` [${d}]` : ""}: `);
        if (line === null) return null;
        const value = line.trim() === "" ? d : line.trim();
        const reason = value === null ? "an answer is required" : q.check(value);
        if (reason === null && value !== null) return value;
        console.log(`  ${reason}`);
    }
}

/** The wizard: asks the questions not answered, then the confirmation; an exit code to stop with, or null to write. */
async function wizard(root: string, answers: Answers): Promise<number | null> {
    const reader = lineReader();
    try {
        let asked = false;
        for (const q of QUESTIONS) {
            if (answers[q.key] !== undefined) continue;
            const d = q.default(root);
            if (!q.asked) {
                if (d !== null) answers[q.key] = d;
                continue;
            }
            asked = true;
            const value = await ask(reader, q, d);
            if (value === null) {
                console.error("error: the input ended before every question was answered; nothing was written");
                return 2;
            }
            answers[q.key] = value;
        }
        if (!asked) return null;
        console.log("\nSummary:");
        for (const q of QUESTIONS) console.log(`  ${q.key}: ${answers[q.key]}`);
        const confirm = await reader.ask("Write the brain? [Y/n]: ");
        if (confirm === null || !/^(y|yes|)$/i.test(confirm.trim())) {
            console.log("Nothing was written.");
            return 1;
        }
        return null;
    } finally {
        reader.close();
    }
}

/** Prints what was written and checks the result with `lint`, which also reports out-of-date views. */
export function report(root: string, result: ScaffoldResult): number {
    for (const p of result.written) console.log(`wrote ${p}`);
    for (const w of result.warnings) console.error(`warning: ${w}`);
    for (const n of result.notes) console.error(`note: ${n}`);
    const violations = lint(loadRepo(root)).violations;
    for (const v of violations) console.log(formatViolation(v));
    if (violations.some((v) => severity(v.rule) === "error")) return 1;
    console.log(
        `\nThe skeleton of the brain is ready and valid. Open your AI agent in ${root} and tell it:\n\n  ${result.prompt}\n`,
    );
    return 0;
}

export async function runInit(args: string[]): Promise<number> {
    let parsed: Parsed;
    try {
        parsed = parseArgs(args);
        preflight(parsed.root);
    } catch (e) {
        return failed(e);
    }
    const { root, answers, yes } = parsed;
    const missing = QUESTIONS.filter((q) => answers[q.key] === undefined);
    if (yes || missing.every((q) => !q.asked)) {
        const key = takeDefaults(root, answers, missing);
        if (key !== null) {
            console.error(`error: no answer for ${key} and no default; give --${key}`);
            return 2;
        }
    } else {
        const stop = await wizard(root, answers);
        if (stop !== null) return stop;
    }
    let result: ScaffoldResult;
    try {
        result = scaffold(root, answers);
    } catch (e) {
        return failed(e);
    }
    return report(root, result);
}
